#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Third-party accounts and secrets for the site (issue #3). Contains no secret
# values: everything is typed in at run time, saved to the git-ignored .env and
# to the GitHub Actions environment below.
GH_ENVIRONMENT="${GH_ENVIRONMENT:-production}"
CF_API="https://api.cloudflare.com/client/v4"

_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# env_secret NAME VALUE sets a secret on the GitHub Actions environment.
env_secret() {
  if _gh_ready && printf '%s' "$2" | gh secret set "$1" --env "$GH_ENVIRONMENT" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$1")
    printf '  %s✓ set%s GitHub secret %s (env: %s)\n' "$GREEN" "$RESET" "$1" "$GH_ENVIRONMENT"
  else
    SKIPPED+=("GitHub secret $1 (gh secret set $1 --env $GH_ENVIRONMENT)")
    warn "skipped GitHub secret $1: gh not ready; set it later"
  fi
}

# env_var NAME VALUE sets a (non-secret) variable on the GitHub Actions environment.
env_var() {
  if _gh_ready && gh variable set "$1" --env "$GH_ENVIRONMENT" --body "$2" >/dev/null 2>&1; then
    printf '  %s✓ set%s GitHub variable %s (env: %s)\n' "$GREEN" "$RESET" "$1" "$GH_ENVIRONMENT"
  else
    SKIPPED+=("GitHub variable $1 (gh variable set $1 --env $GH_ENVIRONMENT)")
    warn "skipped GitHub variable $1: gh not ready; set it later"
  fi
}

# _http_code URL [curl args...] prints only the HTTP status, never the body.
# curl already prints 000 when the request can't be made.
_http_code() {
  local url="$1"; shift
  curl -s -o /dev/null -w '%{http_code}' "$@" "$url" || true
}

# _authed_code TOKEN URL [curl args...] is _http_code with a Bearer token fed
# through stdin (curl -K -), so the token never shows up in the process list.
_authed_code() {
  local token="$1"; shift
  printf 'header = "Authorization: Bearer %s"\n' "$token" | _http_code "$@" -K -
}

# require KEY "Prompt" [secret] re-asks until the value is non-empty.
require() {
  local asker=ask
  [[ "${3:-}" == secret ]] && asker=ask_secret
  while :; do
    "$asker" "$1" "$2"
    [[ -n "${!1}" ]] && return
    warn "a value is required"
  done
}

# Plain address with no quotes, backslashes or spaces, so it's safe inside JSON.
_EMAIL_RE='^[^@"\\[:space:]]+@[^@"\\[:space:]]+\.[^@"\\[:space:]]+$'

run_wizard() {

TOTAL_STAGES=6

banner "Website: third-party accounts and secrets"

stage "GitHub: environment"
say "Values go to your local .env (git-ignored) and to the GitHub Actions"
say "environment '$GH_ENVIRONMENT'. CI jobs read them with: environment: $GH_ENVIRONMENT"
if _gh_ready; then
  if confirm "Create or update the '$GH_ENVIRONMENT' environment on GitHub now?"; then
    if gh api -X PUT "repos/{owner}/{repo}/environments/$GH_ENVIRONMENT" >/dev/null; then
      printf '  %s✓ environment%s %s ready\n' "$GREEN" "$RESET" "$GH_ENVIRONMENT"
    else
      warn "couldn't create the environment; create it under Settings → Environments"
    fi
  fi
else
  warn "gh isn't installed or logged in (gh auth login); GitHub steps will be skipped."
fi
pause

stage "Cloudflare: account ID"
say "Sign up or log in to Cloudflare (the free plan is enough)."
open_url "https://dash.cloudflare.com/"
step "On Account home, open the ⋯ menu next to your account name → Copy account ID."
note "It's also shown under Workers & Pages → Account details, on the right."
require CLOUDFLARE_ACCOUNT_ID "Paste the account ID:"
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
env_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
pause

stage "Cloudflare: API token for OpenTofu"
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Create Custom Token. Name it e.g. 'website-opentofu'."
step "Permissions (all Account-level):"
note "    Account · Cloudflare Pages · Edit"
note "    Account · Turnstile · Edit"
note "    Account · Account Settings · Edit   (needed for Web Analytics)"
note "    Account · Workers R2 Storage · Edit (only if OpenTofu state lives in R2)"
step "Account Resources: Include → your account. Continue to summary → Create Token."
step "Copy the token (it's shown only once)."
require CLOUDFLARE_API_TOKEN "Paste the API token:" secret
write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
env_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
say "Checking what the token can reach (status codes only):"
cf_check() {
  local label="$1" path="$2" code
  code=$(_authed_code "$CLOUDFLARE_API_TOKEN" "$CF_API/accounts/$CLOUDFLARE_ACCOUNT_ID/$path")
  if [[ "$code" == 200 ]]; then note "  ✓ $label"; else warn "$label: HTTP $code (missing permission?)"; fi
}
cf_check "Pages" "pages/projects"
cf_check "Turnstile" "challenges/widgets"
cf_check "Web Analytics" "rum/site_info/list"
pause

stage "Resend: API key"
say "Resend sends the contact-form emails using its shared sender (no domain needed)."
open_url "https://resend.com/api-keys"
step "Sign up or log in, then Create API key."
step "Name it e.g. 'website-contact', permission 'Sending access', domain 'All domains'."
step "Copy the key (starts with re_, shown only once)."
require RESEND_API_KEY "Paste the API key:" secret
write_env RESEND_API_KEY "$RESEND_API_KEY"
env_secret RESEND_API_KEY "$RESEND_API_KEY"
resend_post() {
  _authed_code "$RESEND_API_KEY" "https://api.resend.com/emails" \
    -X POST -H 'Content-Type: application/json' -d "$1"
}
code=$(resend_post '{}')
# An empty payload with a valid key fails validation (422), not auth (401/403).
if [[ "$code" == 422 ]]; then note "  ✓ key accepted"; else warn "unexpected HTTP $code: check the key"; fi
pause

stage "Resend: destination inbox"
warn "Without a verified domain, Resend only delivers to the email you signed up with."
while :; do
  require CONTACT_TO_EMAIL "Email address that receives contact-form leads:"
  [[ "$CONTACT_TO_EMAIL" =~ $_EMAIL_RE ]] && break
  warn "that doesn't look like an email address"
done
write_env CONTACT_TO_EMAIL "$CONTACT_TO_EMAIL"
env_secret CONTACT_TO_EMAIL "$CONTACT_TO_EMAIL"   # secret: keeps it out of public CI logs
if confirm "Send a test email to that address now?"; then
  code=$(resend_post "{\"from\":\"Website <onboarding@resend.dev>\",\"to\":[\"$CONTACT_TO_EMAIL\"],\"subject\":\"Website setup test\",\"text\":\"Resend is wired up.\"}")
  if [[ "$code" == 200 ]]; then note "  ✓ sent: check your inbox (and spam)"; else warn "send failed: HTTP $code"; fi
fi
pause

stage "Cal.com: Discovery call · 30 min"
open_url "https://app.cal.com/event-types"
step "Sign up or log in, then New → title 'Discovery call · 30 min', duration 30 → Continue."
step "Set location (e.g. Cal Video), availability, then Save."
step "Copy the public link (⧉ icon on the event), e.g. https://cal.com/<user>/discovery-call"
require CALCOM_BOOKING_URL "Paste the booking URL:"
write_env CALCOM_BOOKING_URL "$CALCOM_BOOKING_URL"
env_var CALCOM_BOOKING_URL "$CALCOM_BOOKING_URL"
code=$(_http_code "$CALCOM_BOOKING_URL" -L)
if [[ "$code" == 200 ]]; then note "  ✓ booking page is reachable"; else warn "booking page returned HTTP $code"; fi
note "Use this URL as the Cal.com booking URL in the site settings."
pause

finish
}

run_wizard "$@"; exit
